import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Application } from 'src/app/auth/Models/Application';
import { Job } from 'src/app/landing/models/job';
import { ApplicationService } from 'src/app/service/application/application.service';
import { JobService } from 'src/app/service/job/job.service';

@Component({
  selector: 'app-applicants-list',
  templateUrl: './applicants-list.component.html',
  styleUrls: ['./applicants-list.component.css']
})
export class ApplicantsListComponent implements OnInit {

  job!: Job;
  applicants: Application[] = [];

  constructor(
    private appService: ApplicationService,
    private jobService: JobService,
    private route: ActivatedRoute
  ) {}

  ngOnInit(): void {
    this.getApplicantsByJob();
    this.getJobById();
  }

  getApplicantsByJob() {
    this.appService.getApplicationByJob(Number(this.route.snapshot.paramMap.get('jobId')))
      .subscribe(res => this.applicants = res);
  }

  getJobById() {
    this.jobService.getJobById(Number(this.route.snapshot.paramMap.get('jobId')))
      .subscribe(res => this.job = res);
  }
}
<div class="page">
<app-header variant="company"></app-header>
<div class="app-shell">
<app-sidebar variant="company"></app-sidebar>
<main class="main-wide">

<div class="breadcrumb">Manage Jobs / <span>{{job?.jobTitle}}</span></div>
<div class="section-head"><h2>{{applicants.length}} applicants</h2></div>
<div class="tab-row"><span class="tab active">All</span><span class="tab">Pending</span><span class="tab">Approved</span></div>
<div class="table-wrap">
  <table>
    <thead><tr><th>Applicant</th><th>Applied On</th><th>Status</th><th></th></tr></thead>
    <tbody>
      <tr *ngFor="let app of applicants">
        <td>{{app.jobSeekerName}}</td>
        <td>{{app.appliedDate}}</td>
        <td><span class="chip" [ngClass]="{'chip-open': app.status === 'APPROVED', 'chip-rejected' : app.status === 'REJECTED', 'chip-pending' : app.status === 'PENDING'}">{{app.status}}</span></td>
        <td class="actions"><a [routerLink]="['/company/company/applicant', app.id]">Review</a></td>
      </tr>
    </tbody>
  </table>
</div>

</main>
</div>
</div>
